--
-- Structure de la table `demandes`
--
DROP TABLE IF EXISTS `demandes`;
CREATE TABLE `demandes` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `titre` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type_demande` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `statut` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EN_ATTENTE',
  `utilisateur_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_demandeur` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom_demandeur` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email_manager` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `statut_n1` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EN_ATTENTE',
  `date_validation_n1` datetime(3) DEFAULT NULL,
  `commentaire_n1` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statut_rh` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EN_ATTENTE',
  `date_validation_rh` datetime(3) DEFAULT NULL,
  `commentaire_rh` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_debut` datetime(3) DEFAULT NULL,
  `date_fin` datetime(3) DEFAULT NULL,
  `nombre_jours` double DEFAULT NULL,
  `type_conge` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `motif` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `piece_jointe` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `donnees_formulaire` json DEFAULT NULL,
  `cree_le` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `mis_a_jour_le` datetime(3) NOT NULL ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `demandes_utilisateur_id_fkey` (`utilisateur_id`),
  CONSTRAINT `demandes_utilisateur_id_fkey` FOREIGN KEY (`utilisateur_id`) REFERENCES `utilisateurs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

