--
-- Structure de la table `reservations_salles`
--
DROP TABLE IF EXISTS `reservations_salles`;
CREATE TABLE `reservations_salles` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `salle_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `titre` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `demandeur_nom` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `demandeur_email` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date` datetime(3) NOT NULL,
  `heure_debut` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `heure_fin` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `participants` int DEFAULT '1',
  `motif` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statut` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CONFIRMEE',
  `cree_le` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `mis_a_jour_le` datetime(3) NOT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `reservations_salles_salle_id_fkey` (`salle_id`),
  CONSTRAINT `reservations_salles_salle_id_fkey` FOREIGN KEY (`salle_id`) REFERENCES `salles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

