--
-- Structure de la table `utilisateurs`
--
DROP TABLE IF EXISTS `utilisateurs`;
CREATE TABLE `utilisateurs` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `azure_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nom` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EMPLOYE',
  `email_manager` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `est_rh` tinyint(1) NOT NULL DEFAULT '0',
  `departement` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `poste` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cree_le` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `mis_a_jour_le` datetime(3) NOT NULL ON UPDATE CURRENT_TIMESTAMP(3),
  `est_com` tinyint(1) NOT NULL DEFAULT '0',
  `est_drh` tinyint(1) NOT NULL DEFAULT '0',
  `est_rh_print` tinyint(1) NOT NULL DEFAULT '0',
  `est_gestionnaire_salle` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `utilisateurs_email_key` (`email`),
  UNIQUE KEY `utilisateurs_azure_id_key` (`azure_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

