--
-- Structure de la table `videos_intranet`
--
DROP TABLE IF EXISTS `videos_intranet`;
CREATE TABLE `videos_intranet` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `titre` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `categorie` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Institutionnel',
  `duree` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT '5 min 00 s',
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `thumbnail_url` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cree_le` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `mis_a_jour_le` datetime(3) NOT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
